struct LongHashCounterL {
    std::vector<long long> keys;
    std::vector<long long> allocated;
    int scale = 4;
    int rscale = 2;
    int mask = scale - 1;
    int size = 0;
    const long long NG = 0;

    LongHashCounterL() {
        allocated.assign(scale, NG);
        keys.assign(scale, 0);
    }

    bool containsKey(long long x) {
