        int pos = h(x) & nmask;
        while (nallocated[pos] != NG) pos = (pos + 1) & nmask;
        nkeys[pos] = x;
        nallocated[pos] = v;
        allocated = nallocated;
        keys = nkeys;
        scale = nscale;
        rscale = nrscale;
        mask = nmask;
